class JSONEncoder(json.JSONEncoder):
    def default(self, obj):
        try:
            return dict(obj)
        except TypeError:
            pass
        return super().default(obj)


try:
    JSONProviderBase = flask.json.provider.JSONProvider
except AttributeError:
    pass
